insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 1, 'Under the Poisson count model, what is the count a site records over a year?', '["The true rate of the workforce, measured exactly once the hours are known and the base is named.", "The mean of the distribution itself, since the model sets the recorded count equal to its mean.", "One draw around a mean equal to the true rate times the exposure.", "A draw whose spread the caller must supply separately as a standard deviation."]'::jsonb, 2, 'The model says a workforce has a true rate, the true rate times the exposure gives a mean count, and the recorded count is one draw around that mean. Treating the count as the true rate, or as the mean itself, ignores that another year on the same hours could have drawn five cases or nine where the BLS example drew 7.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 2, 'Why does neither `rateConfidenceInterval` nor `compareRates` ask the caller for a standard deviation?', '["Once the mean is known, the Poisson distribution fixes how widely counts scatter around it.", "Both functions assume a default spread of one event, which suits the small counts most sites record.", "They estimate a spread from the monthly rates, the way a normal approximation would.", "The base supplies it."]'::jsonb, 0, 'The Poisson count model carries its own spread: the mean fixes the scatter, so no second number is needed. A normal approximation built from monthly rates is a different method, and it is the one that fails on the small counts safety work usually has.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 3, 'Which real situation strains an assumption the Poisson count model takes for granted?', '["A month in which the crew works fewer hours than usual, so its exposure is small.", "A site that reports on the 1,000,000 base where its neighbour uses the 200,000 base.", "A crew whose true rate is high, so that it records many events over the year and the count grows large.", "One bad job injures three people at once."]'::jsonb, 3, 'The model assumes events arrive one at a time and independently. Three injuries from one job are plainly dependent, and real counts then scatter wider than the model says. A short month is handled by the model through its hours, and the base only rescales the figure.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 4, 'On the IMO ladder, 1 event in 100000 hours and 100 events in 10000000 hours both read 2.000000 per 200,000 hours. The upper limits are 11.143287 and 2.432536. What does that pair show?', '["The larger workforce has the lower true rate, because its upper limit is lower than the other one.", "The count underneath sets how sure the rate is, and the rate alone cannot tell the two apart.", "One of the two rows must have been computed on a different base, since equal rates on one base carry equal limits.", "The engine rounds small counts upwards, which inflates the upper limit on the first row."]'::jsonb, 1, 'Both rows read the same observed rate, so neither shows a lower true rate. What differs is the count, 1 against 100, and the Poisson count model makes the interval on 1 event far wider. Nothing about the base or any rounding differs between the rows.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 5, 'On the IMO ladder at 1 event, what is the upper 95 percent limit divided by the lower one?', '["5.546326, which is the width of the interval measured against the rate on that row", "29.828286, which is the same ratio read on the second rung of the ladder", "220.068159", "1.494848, which is the ratio at the top of the ladder at 100 events"]'::jsonb, 2, 'The row for 1 event reads 0.050636 to 11.143287, and the course gives their ratio as 220.068159. The figure 5.546326 is the width over the rate, a different column, and 29.828286 belongs to 2 events.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 6, 'The IMO ladder''s ratio of limits falls from 220.068159 to 29.828286 between 1 and 2 events, and only from 1.776261 to 1.494848 between 50 and 100. What does that say about adding exposure?', '["Every doubling of the exposure narrows the interval by the same factor.", "Exposure stops mattering once a site passes 50 events.", "It is a rounding effect of printing six decimals.", "Most of the certainty arrives early, so the first few extra events narrow the interval far more than later ones."]'::jsonb, 3, 'A hundred times the exposure buys a great deal of certainty, and the first steps buy most of it. The step from 50 to 100 still narrows the interval, just by less, so exposure keeps mattering. The ratios are the engine''s own limits divided, and no rounding is involved.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 7, 'UGHELLI recorded 9 recordable cases in 2318640 hours and reads 0.776317 per 200,000 hours. What does that observed rate estimate?', '["The true rate of that workforce over those hours, with events classified the way the site classified them.", "The rate UGHELLI will record next year, provided the hours stay near 2318640.", "The rate of any sister site doing the same work under the same management.", "The industry rate for comparable work, which the observed rate reads directly."]'::jsonb, 0, 'The target of an observed rate is narrow: this workforce, these hours, this site''s classification. It says nothing on its own about next year, a sister site or an industry figure, each of which is a different quantity with its own data.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 8, 'The ABO crew recorded 0 recordables in 41300 hours, so its observed rate is 0. What does the engine''s 95 percent interval say about the crew?', '["Its true rate is zero, since the lower and the upper limit both collapse onto the observed count.", "Its true rate could be as high as 17.863823 per 200,000 hours.", "Nothing: the engine refuses a count of zero.", "Its true rate is at least 0.776317, the UGHELLI figure, because a zero is always too good to be true."]'::jsonb, 1, 'A zero is an estimate too. The engine returns a lower limit of 0.000000 and an upper limit of 17.863823 per 200,000 hours, far above every other observed rate in the lesson''s table. A count of zero is a legitimate input and is never refused, and no lower bound from another site applies.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 9, 'UGHELLI''s observed FAR is 0.000000 on 0 fatalities in 2318640 hours. Which reading of that figure is sound?', '["It shows UGHELLI''s true fatality rate sits below IOGP''s 2024 observed FAR of 0.769438.", "It is exact, since FAR is the one rate with a fixed base and a fixed base leaves no uncertainty behind.", "It proves the site''s risk of a fatality over those hours was zero.", "It records what happened on those hours and bounds nothing until an interval is put beside it."]'::jsonb, 3, 'An observed FAR on a few million hours with no fatalities describes the record and nothing more; the upper limit on a zero count is what bounds it. A fixed base fixes the scale of the figure and has nothing to say about how sure it is, and a zero on those hours cannot beat a figure resting on 32 fatalities in 4158877000 hours.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 10, 'In the AKASO stream, month 11 logged 1 recordable in 18240 hours and read 10.964912, and month 12 logged none in 222150 hours and read 0.000000. What best explains the swing?', '["The true rate spiked in month 11 and then recovered.", "The two months were reported on different bases.", "One event landed in very few hours, then no event landed in many.", "The engine cannot rate a month that short, so the 10.964912 is an artefact of refusing and retrying."]'::jsonb, 2, 'Nothing the rates can show changed between the two months. A thin denominator puts a small mean under the Poisson distribution, and swings like this follow as a matter of course. The engine rates any month with hours above zero, and every AKASO rate is on the 200,000 base.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 11, 'AKASO''s first rolling window pools twelve months and reads 1.208038, where the short month alone read 10.964912. Why is pooling the first defence against wide swings?', '["The window carries 13 events, which moves the reading down the ladder from 1 event.", "The window averages the twelve monthly rates to 2.026485, and averaging smooths the swings out.", "Pooling drops the short month from the window, which removes the source of the swing entirely.", "Pooling switches to the 1,000,000 base."]'::jsonb, 0, 'Sum then divide puts 13 events over the window''s hours, and a larger count carries a narrower interval, which is the IMO ladder''s lesson. The mean of the monthly rates, 2.026485, is a different figure that still weights the short month''s 10.964912 like a full month, and the window keeps the short month in it.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 12, 'A report quotes the BLS case on the 1,000,000 base instead of the 200,000 base. What happens to the interval relative to the rate?', '["It narrows, as more hours sit behind it.", "It widens fivefold, the ratio of the bases.", "It is undefined until the base is confirmed.", "It does not change: limits and rate move in step."]'::jsonb, 3, 'The interval is worked on the count and then multiplied by the base over the hours, exactly as the rate is. Naming a different base rescales the rate and both limits together and changes nothing about how sure the figure is. The hours stay 400000 whatever base is named.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 13, 'A monthly report prints a bare 2.000000 per 200,000 hours. What should a reader ask for before deciding how much weight it carries?', '["The crew''s headcount.", "The count and the hours behind it.", "Last month''s rate, for the trend.", "The company''s usual base."]'::jsonb, 1, 'With the count and the hours, and the base already printed, a reader can run the interval in the explorer, and it shows which rung of the ladder the figure came from: 0.050636 to 11.143287 at 1 event, 1.627280 to 2.432536 at 100. Headcount is no input to the engine at all, and the base only rescales.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 14, 'IOGP''s 2024 observed FAR of 0.769438 carries a 95 percent interval of 0.526295 to 1.086218. Why is that a range a reader can work with?', '["It rests on 4158877000 hours, and hours on that scale make the figure exact.", "Its base is fixed, removing the doubt.", "It rests on 32 fatalities, a respectable count.", "IOGP rounds it to 0.77 when publishing."]'::jsonb, 2, 'What sets the width of an interval relative to its rate is the number of events, and 32 is enough for a usable range. The hours are vast, and the interval is still real because the Poisson count model draws the events. A fixed base fixes the scale only.'),
  ('safetystats', 'intermediate', 'module', 'm01-a-count-is-a-draw', 15, 'The day crew in the Associate headcount lesson logged 1 recordable in 80000 hours and read 2.500000 per 200,000 hours. Which rung of the IMO ladder does its interval most resemble?', '["The first rung, which rests on 1 event and reads 0.050636 to 11.143287.", "The top rung, since 2.500000 is close to the ladder''s rate of 2.000000 and the count does not matter.", "The rung for 10 events, because 80000 hours is a full year for a crew of 40 people.", "None: a crew rate carries no interval."]'::jsonb, 0, 'The width of an interval relative to its rate is set by the count, and the day crew''s rate rests on 1 event, the same as the first rung. Its interval will be very wide. Being near the ladder''s rate says nothing about which rung it sits on, and every rate the engine computes can carry an interval.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 1, 'For a count of 7 at 95 percent, how many degrees of freedom do the engine''s two chi-square quantiles use?', '["14 for both, as both use 2N.", "14 for the lower limit and 16 for the upper limit.", "16 for both, as both use 2N + 2.", "7 for the lower limit and 8 for the upper, the count and one more, with no doubling."]'::jsonb, 1, 'The Garwood limits are chi2(alpha/2; 2N)/2 and chi2(1 - alpha/2; 2N + 2)/2, so at N = 7 the lower uses 14 and the upper uses 16. Using 2N on both sides puts the upper limit too low, and using the count itself forgets that twice a gamma of shape k is a chi-square on 2k degrees of freedom.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 2, 'Why does the Garwood upper limit use 2N + 2 degrees of freedom where the lower uses 2N?', '["A continuity correction of two degrees of freedom is added on the upper side to make the interval conservative.", "The upper tail sits at 1 - alpha/2, which is larger than alpha/2 and so needs more degrees of freedom.", "The two extra degrees of freedom carry the base and the hours.", "The upper limit is a gamma quantile of shape N + 1, and twice a gamma of shape k is a chi-square on 2k degrees of freedom."]'::jsonb, 3, 'The upper limit is the Poisson mean at which N or fewer events has probability alpha/2, a quantile of the gamma distribution of shape N + 1, and doubling it gives 2N + 2 degrees of freedom. No correction is added; the conservatism comes from the whole-number count. The base and hours enter only afterwards, as a rescaling.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 3, 'At N = 7 and 95 percent, the chi-square lower quantile on 14 degrees of freedom is 5.628726103040. What is the count lower limit?', '["2.814363051520", "5.628726103040, since the quantile is the count limit itself", "1.407182, which is a quarter of that quantile", "3.285315691895, which is the count lower limit at 90 percent"]'::jsonb, 0, 'The count limit is half the chi-square quantile, and the engine''s countLower is 2.814363051520. Forgetting the half returns the quantile itself. A quarter of it, 1.407182, is the BLS rate lower limit, a later step that also scales by 200,000 over 400000, and 3.285315691895 belongs to 90 percent.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 4, 'The BLS count limits are 2.814363051520 and 14.422675361702 for 7 cases in 400000 hours on the 200,000 base. What does the engine multiply them by to get the rate limits?', '["400000 over 200,000, which is two, the hours over the base.", "1,000,000 over 400000, the IOGP base over the hours worked.", "200,000 over 400000, which is one half.", "Nothing: they are the same."]'::jsonb, 2, 'Each count limit is multiplied by the base over the hours, 200,000 over 400000, giving 1.407182 and 7.211338 per 200,000 hours. Inverting the fraction doubles the limits, and the base in the multiplier must be the one named for the rate, 200,000 here.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 5, 'The Garwood table gives count limits of 4.795388696132 and 18.390356042018 for 10 events. If those 10 events were recorded in 1000000 hours, what are the limits per 200,000 hours?', '["4.795388696132 to 18.390356042018, since a count limit needs no scaling to become a rate", "1.221652 to 3.088838, the limits the IMO ladder prints for 20 events on those rates", "0.649395 to 4.667333, the limits the IMO ladder prints for 5 events on those rates", "0.959078 to 3.678071"]'::jsonb, 3, 'Multiplying each count limit by 200,000 over 1000000 gives 0.959078 and 3.678071, exactly the IMO ladder''s row for 10 events. Leaving the count limits unscaled quotes them as rates, and the other two pairs are the ladder''s rows for 20 and 5 events.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 6, 'At 95 percent, how much of the miss does the engine''s central interval leave above its upper limit?', '["5 percent, the whole of alpha, placed above the upper limit.", "2.5 percent.", "0.975, which is one minus alpha over two.", "None of it, since an upper limit is meant to be certain."]'::jsonb, 1, 'The engine''s interval is central: it splits alpha evenly and leaves alpha/2 in each tail, which is 2.5 percent at 95 percent. Putting the whole 5 percent above the upper limit is the one-sided construction, and 0.975 is the probability below the limit.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 7, 'A learner asks for 95 percent on a count of 7 but puts the whole 5 percent in each tail. Which count limits does that produce?', '["3.285315691895 and 13.148113802432, the central 90 percent limits.", "2.814363051520 and 14.422675361702, the central 95 percent limits.", "2.037337478700 and 17.133593268913, the central 0.990000 limits.", "3.894766804876 and 11.770914461548, the central 0.800000 limits, where 10 percent sits in each tail."]'::jsonb, 0, 'Five percent in each tail is a central 90 percent interval, which the course gives for 7 as 3.285315691895 to 13.148113802432. The engine''s 95 percent interval halves alpha and reads 2.814363051520 to 14.422675361702. The tempting mistake is to forget the halving, and the result is an interval that is too narrow for the label it carries.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 8, 'For a count of 7, the upper limit climbs from 11.770914461548 to 17.133593268913 between 0.800000 and 0.990000, while the lower falls only from 3.894766804876 to 2.037337478700. Why does the upper side move further?', '["The upper side uses two more degrees of freedom, which adds a fixed width at every confidence.", "The lower limit is floored at zero and so stops moving.", "A count cannot fall below zero and has no ceiling, so the Poisson distribution is skewed to the right.", "Floating point rounding grows with the size of the limit."]'::jsonb, 2, 'The right skew gives the upper tail further to stretch as the miss is squeezed, which is also why the interval is lopsided around the count. The extra degrees of freedom come from the gamma shape, add no fixed width, and the lower limit of 7 is well above zero at every level in the table.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 9, 'At every true mean the course probes, the coverage of the 95 percent interval is at or above 0.95. Why can it never be exactly 95 percent at every mean?', '["The engine adds a margin with 2N + 2 on both limits.", "Alpha in floating point is 0.050000000000000044, so the target itself sits slightly off 95 percent.", "The coverage check leaves part of the distribution out, as the probabilities it sums fall short of one.", "A count is a whole number, so coverage jumps each time the mean crosses a limit."]'::jsonb, 3, 'At any true mean each count either has an interval that covers the mean or does not, and coverage sums the probabilities of those that do. That set changes only where the mean crosses a limit, so coverage jumps there and cannot sit on 95 percent throughout. The probabilities summed come to 1.000000 at every mean, so nothing was left out, and the floating point alpha is far too small to matter.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 10, 'In the coverage table, which true mean pays the largest excess over 0.95?', '["3.500000, where the coverage is 0.990126.", "20.000000, where the coverage is 0.956795.", "0.500000, where the coverage is 0.985612, as the smallest mean probed.", "10.000000, at 0.975386."]'::jsonb, 0, 'At 3.500000 the coverage is 0.990126, the highest in the table. At 20.000000 the excess is the smallest, 0.956795, because larger counts make the steps finer. The smallest mean probed does not carry the largest excess: 0.985612 is below 0.990126.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 11, 'What does conservative mean for the Garwood interval?', '["It is kept narrow on purpose, so that a sparse count does not alarm the reader of a monthly report.", "It covers the true mean at least as often as its label promises, and pays for that in width.", "It covers the true mean exactly 95 times in a hundred at every true mean, with no excess anywhere.", "It rounds both limits outwards to the sixth decimal."]'::jsonb, 1, 'The exact interval is built so that coverage never falls short, and the excess over 0.95 is paid in width. Under-coverage would make a sparse count look more certain than it is, which in safety work is the costly error. No rounding produces the conservatism.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 12, 'A caller passes confidence 95 to `rateConfidenceInterval` for 7 cases in 400000 hours on the 200,000 base. What does the engine return?', '["The interval 1.407182 to 7.211338, having divided 95 by one hundred on the caller''s behalf.", "A refusal naming `count`, since 95 is read as the number of events.", "A refusal naming `confidence`, in the engine''s own words: confidence must be a fraction strictly between 0 and 1, for example 0.95", "An interval with no upper limit, since a confidence above one covers every rate."]'::jsonb, 2, 'The engine refuses to guess whether 95 meant a percentage, and names the field `confidence`. Quietly dividing by a hundred would be a guess that happens to be right most of the time. A refusal carries no number, so nothing can be mistaken for a limit.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 13, 'Why does `rateConfidenceInterval` have no default confidence?', '["A silent default would give a caller who meant 0.900000 and forgot it an interval nobody asked for.", "A default of 0.95 would make the interval too narrow for the small counts most crews record.", "Every standard sets a different confidence, so the engine cannot compute any interval without a lookup table.", "The default was left out to keep the function signature short."]'::jsonb, 0, 'Requiring the value means every interval the engine returns was asked for at a confidence someone chose. The choice matters: the count upper limit for 7 is 13.148113802432 at 0.900000 and 14.422675361702 at 0.950000. The engine refuses a missing value with the same message it gives for 95.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 14, 'The engine solves the Garwood upper limit on the upper tail at alpha/2, with `chiSquareQuantileUpper`. What reason does the course measure for that choice?', '["In double precision 1 minus 0.025 is not exactly 0.975, so the lower-tail route misses at 95 percent.", "The upper-tail route converges in fewer iterations at every confidence level that the engine accepts.", "Alpha at 0.95 is 0.050000000000000044, and the lower-tail route cannot represent that value.", "The lower-tail route must form 1 minus q, which loses digits as q shrinks and at 1e-17 rounds to exactly 1."]'::jsonb, 3, 'The course shows that 1 minus 0.025 IS the double 0.975, and at q of 0.025 both routes give 7.377758908228. The reason is the rest of the table: the lower-tail route''s error grows to 2.32e-5 at 1e-15, and at 1e-17 the number 1 minus q is 1 and the question cannot be posed. Solve the smaller tail directly.'),
  ('safetystats', 'intermediate', 'module', 'm02-the-exact-interval', 15, 'On 2 degrees of freedom at q of 1e-12, the lower-tail route returns 55.262086475787 against an exact 55.262042231857. What does that show?', '["A flaw in the exact column, since minus 2 ln q cannot be computed to twelve decimals.", "A relative error of 8.01e-7, lost to forming 1 minus a tiny q.", "The upper-tail route''s error, which the lower route corrects.", "An agreement to the last digit printed, as at q of 0.025."]'::jsonb, 1, 'The exact figure is minus 2 ln q, which on 2 degrees of freedom is the chi-square upper quantile, and the upper-tail route matches it at 55.262042231857. The lower route''s relative error at 1e-12 is 8.01e-7. Agreement to the last digit printed happens only at 0.025, where both routes give 7.377758908228.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 1, 'At a count of zero, why is the engine''s lower limit 0.000000 at every confidence?', '["The raw lower limit comes out negative, and the engine floors it at zero and flags it.", "A zero count is refused on the lower side, and the engine fills the gap with a zero.", "Zero or more events has probability one at every mean, so no positive mean leaves alpha/2 there.", "The lower limit is always the observed rate, and the observed rate here is 0."]'::jsonb, 2, 'The lower limit asks for the mean at which the observed count or more has probability alpha/2, and zero or more always happens. The chi-square form agrees: with 2N degrees of freedom and N of zero the lower quantile is zero. Nothing is floored or filled in, and for a count of 7 the lower limit sits well away from the observed rate.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 2, 'At 0.950000, the engine''s count upper limit at zero events is which figure?', '["3.688879454114, minus the natural log of 2.5 percent.", "2.995732273554, minus the natural log of 5 percent.", "3, which is the rule of three applied to the count.", "5.298317366548, minus the natural log of half of one percent."]'::jsonb, 0, 'The probability of zero events at a mean mu is e to the minus mu, and setting it equal to half the miss gives minus ln of 2.5 percent, 3.688879454114. The figure 2.995732273554 puts the whole 5 percent in the upper tail, the alpha-not-halved mistake, and 5.298317366548 is the 0.990000 limit.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 3, 'The ABO crew worked 41300 hours with 0 recordables. What is the engine''s central 95 percent upper limit per 200,000 hours?', '["14.527845, which is the rule of three on these hours", "14.507178, which is the central 90 percent limit", "25.657711, which is the central 0.990000 limit", "17.863823"]'::jsonb, 3, 'The count upper limit 3.688879454114 times 200,000 over 41300 is 17.863823. The rule of three gives 14.527845 and the central 90 percent limit 14.507178; both answer the one-sided question, which is a different one from the engine''s central 95 percent.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 4, 'The rule of three approximates a one-sided 95 percent upper limit at zero events. Which central interval from the engine gives that one-sided limit exactly?', '["The central 95 percent interval, which the engine returns by default whenever no level is asked for.", "The central 90 percent interval, which leaves 5 percent in its upper tail.", "The central 0.800000 interval, which leaves 20 percent in the upper tail.", "None, since the engine has no route to a one-sided limit."]'::jsonb, 1, 'A one-sided 95 percent limit leaves the whole 5 percent above it, and a central 90 percent interval leaves exactly 5 percent in each tail. The engine returns its upper limit as 2.995732273554. The central 95 percent interval leaves only 2.5 percent above, and the engine has no default confidence at all.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 5, 'Three over 2.995732273554 is 1.001425. What does that figure measure?', '["How far the rule of three falls below the engine''s central 95 percent limit at zero.", "The coverage excess of the Garwood interval at a mean of 3.", "How close the rule of three comes to the exact one-sided 95 percent limit at zero events.", "The ratio of the 90 and 95 percent rate limits on the ABO hours."]'::jsonb, 2, '2.995732273554 is the count upper limit of the central 90 percent interval, which is the one-sided 95 percent limit. Three over it is 1.001425, so the rule of three is almost exact for the question it answers. Against the central 95 percent limit, 3.688879454114, the gap is far larger.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 6, 'A safety report quotes 17.863823 per 200,000 hours for the ABO crew and labels it a rule of three figure. What is wrong?', '["17.863823 is the engine''s central 95 percent limit; the rule of three gives 14.527845 on those hours.", "Nothing, since the rule of three and the engine''s central 95 percent limit are the same thing.", "The rule of three cannot be used on fewer than 200,000 hours of exposure.", "The figure should be 25.657711, as the rule of three is a limit set at 0.990000."]'::jsonb, 0, 'The rule of three puts 3 events over the exposure, 14.527845 on the ABO hours, and answers a one-sided question. The central 95 percent limit of 17.863823 is a different claim, and quoting it as a rule of three figure overstates the limit by more than a fifth.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 7, 'At zero events the central 95 percent interval''s upper limit sits above the one-sided 95 percent limit. Why?', '["It uses 2N + 2 degrees of freedom, which the one-sided limit leaves out entirely.", "It rounds the count upper limit up to the next whole event before scaling.", "It adds a continuity correction that a one-sided limit never carries.", "It spends half its miss guarding a lower side that cannot be breached."]'::jsonb, 3, 'At zero events the lower limit is 0 anyway, so the 2.5 percent reserved below it buys nothing, and only 2.5 percent is left in the upper tail. The one-sided limit puts the whole 5 percent there and so sits lower. Both use the same shape of quantile; nothing is rounded or corrected.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 8, 'Suppose the ABO crew had logged double its hours and still recorded nothing. Where would its 90 percent limit, now 14.507178, move?', '["14.507178 unchanged, since a zero is a zero whatever the hours behind it happen to be.", "Half of 14.507178, because the count upper limit 2.995732273554 does not move.", "14.507178 divided by the square root of two, as the width shrinks with the root of the exposure.", "0.000000, since doubled hours with no events settle the rate at zero."]'::jsonb, 1, 'The count upper limit at zero depends only on the confidence. The rate limit is that count limit times 200,000 over the hours, so doubling the hours halves it exactly. The square root rule belongs to a normal approximation, and a rate limit at zero never reaches 0.000000 on finite hours.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 9, 'At 95 percent with zero events, how many hours does a crew need to bring its upper limit down to 1.000000 per 200,000 hours?', '["368887.945411, which is the figure for a target of 2.000000", "1475551.781646, which is the figure for a target of 0.500000", "737775.890823", "41300, the ABO crew''s own hours, since the limit is already met"]'::jsonb, 2, 'The hours needed are the count upper limit times 200,000 over the target: 3.688879454114 times 200,000 over 1.000000 is 737775.890823, which the engine confirms. The other figures are the table''s rows for other targets, and the ABO crew''s 41300 hours leave its limit at 17.863823.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 10, 'With zero events, a crew wants its 95 percent upper limit to rule out 0.250000 per 200,000 hours where it now rules out 1.000000. How do the hours needed change?', '["They double, since the target has been cut by a factor of two, then by another factor of two.", "They grow sixteenfold, as the hours scale with the square of the target ratio.", "They stay at 737775.890823, since a zero needs no more hours to prove more.", "They grow fourfold, to 2951103.563291."]'::jsonb, 3, 'The hours needed are the count upper limit times 200,000 over the target, so they scale inversely with the target: a quarter of the target needs four times the hours, 2951103.563291 against 737775.890823. Nothing in the formula squares the ratio.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 11, 'To bring the ABO crew''s 95 percent upper limit down to 2.000000 per 200,000 hours with no recordable, how does the exposure needed compare with the 41300 hours it has?', '["It needs 368887.945411 hours, roughly nine times what it has.", "It needs 368887.945411 hours, roughly twice what it has.", "It already qualifies, as its observed rate of 0 is below 2.000000.", "No amount of hours will do it, since a zero can never bring a limit down."]'::jsonb, 0, '368887.945411 over 41300 is a little under nine. An observed rate of 0 is below every target and proves nothing on its own, which is the whole point of the upper limit. More hours with no event bring the limit down in exact proportion.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 12, 'UGHELLI logs 2318640 hours a year. Could a year of zero recordables there rule out 0.250000 per 200,000 hours at 95 percent?', '["Yes, because a site of that size has millions of hours and so its zero is conclusive.", "Yes, because 0.776317 is its usual rate and a zero year beats it comfortably at any target.", "No: that needs 2951103.563291 hours, and a year of UGHELLI falls short.", "The engine refuses a zero on that many hours."]'::jsonb, 2, 'Zero events carries information in proportion to the hours, and ruling out 0.250000 needs 2951103.563291 hours without a recordable. UGHELLI''s year of 2318640 hours is short of it. A usual rate from other years is no part of this calculation, and the engine never refuses a zero count.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 13, 'The same ABO zero reads an upper limit of 11.150533 at 0.800000 and 25.657711 at 0.990000. What must a report that quotes the zero with its upper limit also quote?', '["The rule of three figure, since only it is independent of the confidence and can anchor the other two.", "The confidence, since both limits are true statements about the same crew.", "The lower limit, since the upper limit alone is ambiguous between the two confidence levels.", "The crew''s headcount, since the limit depends on how many people shared the hours."]'::jsonb, 1, 'Moving from 0.800000 to 0.990000 raises the limit from 11.150533 to 25.657711 on the same zero, so without the confidence a reader cannot tell which claim was made. The lower limit is 0.000000 at every level and settles nothing, and the engine has no headcount input.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 14, 'How does the zero events arithmetic apply to UGHELLI''s observed FAR of 0.000000 on 0 fatalities in 2318640 hours?', '["It does not apply, since `fatalAccidentRate` has a fixed base and so carries no interval of its own.", "The rule of three is the only route, since the engine will not take a zero fatality count.", "Use the 200,000 base, since the interval is only defined on the OSHA base.", "Pass the zero count and those hours to `rateConfidenceInterval` on the 100,000,000 base."]'::jsonb, 3, 'The same Garwood arithmetic, with the count upper limit 3.688879454114 at 95 percent, bounds any zero from above on whatever base is named. A fixed base fixes the scale of a FAR and says nothing about how sure it is, and `rateConfidenceInterval` takes any base above zero.'),
  ('safetystats', 'intermediate', 'module', 'm03-zero-events', 15, 'Several small crews doing comparable work each log a short year with zero recordables. What does pooling them do?', '["The pooled zero carries the pooled hours, so its upper limit falls in proportion.", "Nothing, since a sum of zeros is still zero and a zero carries no information.", "It gives a pooled lower limit above zero.", "It is refused, as the engine takes no zero counts."]'::jsonb, 0, 'Sum then divide applies to a count of zero as well: the pooled zero sits over the summed hours, and the upper limit is the count upper limit times the base over those hours. It is legitimate when the crews do comparable work. The lower limit at zero stays 0.000000 however many hours are pooled.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 1, 'ERHA east recorded 6 events in 240500 hours and west 11 in 902700. How does the engine test for a difference without estimating the common rate?', '["It estimates the common rate from all 17 events and then tests each side''s count against it separately.", "It conditions on the total of 17: under equal rates east''s count is binomial with east''s share of the hours as its probability.", "It compares the two rates on the 200,000 base with a normal z test.", "It asks the caller for the common rate."]'::jsonb, 1, 'Given 17 events in total and equal rates, each event is equally likely to land in any hour worked, so east''s count out of 17 is binomial with east''s share of the hours. The unknown rate drops out, which is the point of conditioning; a normal z test on the rates is a different method that needs the rate estimated.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 2, 'What is the ERHA comparison''s expectedProportion, and where does it come from?', '["0.352941, east''s 6 events over the 17 events recorded by the two sides together.", "0.128104, the probability of east recording 6 or more of the 17 under equal rates.", "0.951727, the probability of east recording 6 or fewer of the 17 under equal rates.", "0.210374, east''s hours over all the hours."]'::jsonb, 3, 'Under equal rates the share of events a side should expect is its share of the hours, fixed before a single event is counted: 240500 over the ERHA total hours is 0.210374. East''s actual share of the events, 0.352941, is what the test compares against it, and the other two figures are the tails.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 3, 'ERHA''s lowerTail is 0.951727 and its upperTail 0.128104, which add to more than one. Why?', '["Both tails include the observed count of 6.", "The engine adds a continuity correction to each tail before it returns them.", "The two tails are computed on different probabilities of success.", "Rounding each tail to six decimals inflates both of them."]'::jsonb, 0, 'The lower tail is the probability of 6 or fewer and the upper tail of 6 or more, so the probability of exactly 6 is counted in both. The tails share one binomial, on 17 trials at 0.210374, and rounding moves nothing by the amounts involved.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 4, 'A learner doubles ERHA''s printed upperTail of 0.128104 and gets a figure one unit below the engine''s pValue of 0.256209 in the sixth decimal. What explains the difference?', '["The engine doubles the larger tail, which is why its pValue sits slightly above the doubled upper tail.", "The engine adds the probability of the observed count once more before doubling.", "The engine doubles the unrounded tail; doubling a figure already rounded to six decimals can move the last digit.", "The central p-value is capped at 1, which shifts it upward."]'::jsonb, 2, 'The central p-value is twice the smaller tail, and the smaller tail here is the upper one, but the engine doubles its full-precision value and then prints six decimals. The printed 0.128104 is already rounded, so twice it can differ in the last place. Doubling the larger tail, 0.951727, would pass 1 and be capped, and no cap applies at 0.256209.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 5, '`compareRates` takes counts and hours but no base. Why?', '["It always works on the 200,000 base internally and converts the result back afterwards.", "A ratio of two rates on the same base cancels the base.", "The base is read from the first group''s hours, which set the scale.", "A comparison between two groups has no meaning on the 1,000,000 base."]'::jsonb, 1, 'The comparison reads identically whether both sides reported on 200,000 hours or 1,000,000, because the base appears in the numerator and denominator of the ratio. Leaving it out removes one way to make a mistake. No base is assumed internally at all.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 6, 'ERHA''s rate ratio is 2.047326 with a 95 percent interval of 0.621694 to 6.039396. Which reading is sound?', '["East''s rate is about twice west''s, and the interval confirms it because the ratio sits inside the interval.", "East''s rate is lower, since the lower limit of 0.621694 sits below 1.", "East and west have equal rates.", "The data are consistent with east''s rate somewhat below west''s, equal to it, or six times it."]'::jsonb, 3, 'The interval includes 1 and runs to 6.039396, so at 95 percent it cannot pick out any one of those readings; the point estimate of 2.047326 sits inside it without being singled out. An interval that includes 1 leaves equal rates possible, which is a weaker statement than showing them equal.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 7, 'A learner swaps the ERHA groups so that west is the first group. What happens to the output?', '["The ratio becomes one over 2.047326, and the new upper limit is one over the old lower limit, 0.621694.", "Nothing changes, since the rate ratio of two groups is symmetric in the order in which they are passed to the engine.", "The ratio becomes one over 2.047326, and the new lower limit is one over the old lower limit.", "The p-value becomes one minus 0.256209, since the other tail is now the one the engine doubles."]'::jsonb, 0, 'West over east inverts every figure, and inverting flips the ends: one over the old lower 0.621694 becomes the new upper limit, and one over the old upper 6.039396 the new lower. The central p-value is the same either way, since swapping only exchanges the two tails and the smaller one keeps its value.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 8, 'In the golden compare-first-zero, the first group has 0 events in 180000 hours and the second 6 in 210000. The engine returns a ratio of 0.000000 with an upper limit of 0.990863. What follows at 95 percent?', '["Nothing, since a ratio of zero is undefined and the interval must be ignored.", "Equal rates cannot be ruled out, since the lower limit of 0.000000 touches zero and so the interval spans every ratio.", "Equal rates are ruled out: the first group''s rate is lower, and the p-value of 0.048748 agrees.", "The second group''s rate is lower, since its count is higher."]'::jsonb, 2, 'The upper limit 0.990863 is below 1, so the interval excludes equal rates and places the first group lower. A lower limit of 0.000000 on a ratio says nothing about equality, which sits at 1. A ratio of 0 over something is a legitimate 0.000000.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 9, 'In the golden compare-second-zero, the first group has 4 events in 90000 hours and the second 0 in 150000. What does the engine return for the rate ratio?', '["Infinity, with a lower limit of 1.100207 and an upper limit of Infinity beside it, as JavaScript prints.", "null, with upperUnbounded true, a lower limit of 1.100207 and a reason in the engine''s own words.", "A refusal naming `count2`, since a group with no events has nothing to divide by and cannot be compared.", "0.000000, the same as when the empty group comes first."]'::jsonb, 1, 'Something over zero has no number, so the engine returns null for the ratio and its upper limit, sets upperUnbounded, and gives its reason: count2 is zero: the rate ratio and its upper limit are unbounded. The lower limit 1.100207 still exists and is above 1. One empty group is a legitimate comparison; only both empty is refused.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 10, 'Why does the engine return null with a reason for an unbounded rate ratio, where JavaScript could print Infinity?', '["Infinity would crash the chi-square quantile functions, which cannot accept it as an argument at any confidence.", "Infinity would make the central p-value infinite as well.", "The ratio is zero, and null stands for zero.", "Infinity looks like a number and can be sorted or copied into a report as a finding; null cannot."]'::jsonb, 3, 'A null with a reason cannot be mistaken for a measurement, and upperUnbounded tells a program what kind of absence it holds. The engine keeps whatever part of the interval does exist, here the lower limit 1.100207, which carries the whole finding. The p-value comes from the binomial tails and stays finite, 0.039551 here.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 11, 'A caller passes 0 events in 180000 hours against 0 in 210000 to `compareRates`. What does the engine return?', '["A refusal naming `count1`: count1 and count2 are both zero: the conditional test has no events to condition on", "A ratio of null with upperUnbounded true, as for one empty group placed second.", "A p-value of 1.000000, since two zeros are perfectly consistent with equal rates.", "A refusal naming `count2`, since the second zero is the one that makes the test undefined."]'::jsonb, 0, 'With both counts zero the total is zero, so there is nothing to split, every tail would be one and the ratio zero over zero. The engine refuses, names the first count and puts both in its message, verbatim above. One empty group is a comparison; two are none.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 12, 'Two crews each record zero events. What does the lesson say to do instead of comparing them?', '["Rank them by hours, since the crew with more hours is the safer of the two by construction.", "Pass them to `compareRates` with one event added to each, which is how the test handles zeros.", "Run each through `rateConfidenceInterval` and report both upper limits.", "Report both rates as 0 and treat them as equal."]'::jsonb, 2, 'Two groups with no events are two zero events questions, and each upper limit says how high that crew''s rate could be. Ranking them only ranks their hours, since the crew with more hours has the lower limit and nothing else separates them. Adding events invents data.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 13, 'A comparison passes exposureHours2 as zero. What does the engine return?', '["A ratio of null with upperUnbounded true, as for a group with no events.", "The rate of the first group alone.", "A refusal naming `count2`, since the second group has no events to condition on.", "A refusal naming `exposureHours2`: a rate over no exposure is undefined."]'::jsonb, 3, 'The engine''s own words are: exposureHours2 must be a finite number of hours above zero: a rate over no exposure is undefined. A group with no hours has no rate at all, which is a different condition from a group with hours and no events, which the engine accepts and reports as unbounded.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 14, 'Why must the expected proportion in the conditional test be built from hours and never from headcount?', '["Headcount is refused by the engine as a field name, so hours are simply the only input it can read.", "Under equal rates each hour carries the same chance of an event, so a side''s expected share is its share of the hours.", "Headcount changes during a year, while hours are fixed.", "Hours are always the larger number and so give a finer proportion."]'::jsonb, 1, 'The Associate crews show why: with 1 recordable each they read the same per head, while per hour the day crew reads 1.456000 times the rotation crew. Built from headcount, a side on longer rotations would be expected to hold too few events and look worse than it is. `compareRates` takes hours and has no headcount input at all.'),
  ('safetystats', 'intermediate', 'module', 'm04-comparing-two-rates', 15, 'Why is the ERHA rate-ratio interval, 0.621694 to 6.039396, so wide?', '["The hours on the two sides differ by more than a factor of three, and unequal hours always widen it.", "The engine uses a Wald log interval, which is wide on small counts.", "It rests on 6 and 11 events, and the smaller count dominates the uncertainty.", "The interval is at 0.990000."]'::jsonb, 2, 'A ratio inherits the uncertainty of both counts, and a ratio built on counts in the single figures will almost always carry a wide interval, just as a single small count did on the IMO ladder. The interval is Clopper-Pearson on east''s share, at 95 percent.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 1, 'What is the rule behind the engine''s central two-sided p-value?', '["The sum of the probabilities of every count no more likely than the one observed.", "The smaller tail on its own, since only the observed side of the distribution matters.", "Twice the larger tail, divided by the total count of events recorded by both groups.", "Twice the smaller tail, capped at 1."]'::jsonb, 3, 'The engine''s method line reads: central two-sided p-value (twice the smaller tail, capped at 1). The sum over counts no more likely than the observed one is the minlike convention, and the smaller tail alone is a one-tailed figure that has not been doubled.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 2, 'Why does the central p-value need a cap at 1?', '["The two tails overlap at the observed count, so twice the smaller can occasionally pass 1.", "A p-value above 1 would signal that the rates are certainly equal, and the cap hides that from the reader.", "The engine rounds the tails upwards, which can push the sum past 1 on small counts.", "The cap only applies when one group has no events."]'::jsonb, 0, 'Each tail includes the observed count, so each can be larger than one half, and doubling the smaller can pass 1. The cap keeps the result a probability. No p-value says the rates are equal, and nothing is rounded upwards.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 3, 'UTOROGU north recorded 7 events in 355200 hours and south 6 in 1048900. The engine''s central p-value is 0.051759 and the minlike p-value, derived, is 0.025879. Which agrees with the engine''s rate-ratio interval of 0.991404 to 12.408545?', '["The minlike one: it is below 0.05, and the ratio of 3.445148 is well above 1.", "The central one: it is above 0.05, and the interval includes 1.", "Both agree, since they differ only by a factor of two and 0.05 sits in between them.", "Neither, since the interval is exact and neither p-value is."]'::jsonb, 1, 'An interval that includes 1 does not rule out equal rates, and neither does a p-value above 0.05, so the central one agrees. The minlike figure is below 0.05 and would declare a difference the interval does not support. A point estimate above 1 is no test at all.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 4, 'How is the minlike p-value defined?', '["Twice the smaller tail, left uncapped, which is why it runs below the central figure.", "The smaller of the two tails, reported on its own without doubling, which is why it runs lower.", "The probability of every count no more likely than the one observed, summed over both sides.", "The lowest p-value the engine finds when it sweeps the comparison across every confidence level."]'::jsonb, 2, 'Minlike walks the whole binomial, on both sides, and sums every count whose probability is at or below that of the observed count. It is the convention of R''s poisson.test and of scipy''s binomtest. Doubling the smaller tail is the engine''s central rule, and removing the cap would never lower a p-value.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 5, 'Why can the central and minlike p-values land on opposite sides of 0.05?', '["On a skewed binomial the central rule mirrors the near tail, while minlike counts what is actually there on the far side.", "Minlike uses the normal approximation, and the central rule uses the exact binomial distribution.", "The two are computed at different confidence levels by default.", "The central rule uses the hours and minlike uses the headcount."]'::jsonb, 0, 'When one group has a small share of the hours the binomial is lopsided and the far side holds less probability than the near side. Doubling the near tail counts a mirror image of it; minlike counts the far side as it is. Both are exact, and neither is an error.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 6, 'Why did the engine choose the central convention?', '["It is the convention of R''s poisson.test, which most readers use to check a figure.", "It always gives the smaller p-value, which makes differences easier to find.", "It needs no binomial, only the two tails of a normal curve.", "It is the test the Clopper-Pearson interval inverts (Fay 2010), so the p-value and interval always tell the same story."]'::jsonb, 3, 'The p-value and the interval come from one construction, so they agree by design. The minlike convention is the one R and scipy use, and on UTOROGU the central figure is the larger of the two, 0.051759 against 0.025879.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 7, 'The course sweeps every pair of counts from 0 to 15 north and 0 to 24 south on the UTOROGU hours, except both zero. How often does each p-value disagree with the engine''s interval at 0.05?', '["Central on 14 of the 399, minlike on 0, since minlike is the convention in R and scipy.", "Central on 0 of the 399 comparisons, minlike on 14.", "Both on 14, since the disagreements come from rounding to six decimals.", "Neither ever disagrees, since both are exact tests built on the same binomial distribution."]'::jsonb, 1, 'The central p-value falls below 0.05 exactly when the interval excludes 1 on all 399 comparisons. The minlike p-value, derived, disagrees on 14. Being exact does not make a p-value agree with a particular interval; sharing its construction does.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 8, 'Fourteen disagreements out of 399 is a small share. Why does the lesson call it dangerous?', '["Fourteen is enough to make the engine''s interval unreliable on every comparison it returns, close or not.", "The fourteen are all comparisons with both groups empty.", "A reader who checks a handful in R will usually see a match and conclude the conventions are interchangeable, and they part on close calls.", "The disagreements fall where the counts are largest."]'::jsonb, 2, 'UTOROGU is the shape where they part: a p-value near 0.05 and a limit near 1, which is exactly the kind of comparison a report is argued over. The engine''s own interval and p-value agree on all 399, and the one pair with both groups empty is left out of the sweep.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 9, 'What does inverting a test mean, in the sense the engine''s central p-value and interval share?', '["The p-value is one minus the confidence of the interval, so a confidence of 0.95 gives a p-value of 0.05.", "The interval is recomputed with the two groups swapped, and the p-value read from the new limits.", "The p-value is read off the interval''s midpoint.", "The interval is every rate ratio the test would not reject at the stated level."]'::jsonb, 3, 'Collecting every ratio the test would not reject gives the interval, so the edge of the interval and the 0.05 line of the p-value are one boundary seen from two sides. Swapping the groups only inverts the ratio and its limits.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 10, 'What is a p-value from `compareRates`?', '["The probability, if the rates were equal, of a split at least as lopsided as the one observed.", "The probability that the two rates are equal, given the counts and hours of both groups being compared.", "The probability that east''s rate is higher than west''s.", "The share of the rate ratio''s interval lying above 1."]'::jsonb, 0, 'A small p-value says equal rates would rarely produce a split like this one; a large one says they often would. It is never the probability that the rates are equal and says nothing about the size of a difference, which is what the rate-ratio interval answers.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 11, 'On UTOROGU the central p-value is 0.051759 and the interval runs from 0.991404 to 12.408545. Which summary is sound?', '["North and south have equal rates, since the p-value is above 0.05 and so no difference was found.", "North''s rate is 3.445148 times south''s.", "The data cannot rule out equal rates, and cannot rule out a north rate 12.408545 times the south one.", "The comparison is significant, since 0.051759 rounds to 0.05."]'::jsonb, 2, 'A p-value above 0.05 says the data cannot tell; it does not say the rates are equal. The interval includes 1 and also reaches 12.408545, and both statements are true of the same data. The point estimate alone hides that range, and no rounding moves a verdict.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 12, 'A manager reads ERHA''s central p-value of 0.256209 as permission to treat east and west alike. What has been ignored?', '["The lower tail of 0.951727, which shows east is safer than west on the counts.", "The interval''s upper end of 6.039396, which says east could be six times worse.", "The expected proportion, which shows the hours were unequal and so the p-value does not apply.", "Nothing, since a p-value that large settles the question."]'::jsonb, 1, 'East''s rate is 2.047326 times west''s with an interval of 0.621694 to 6.039396. The honest summary is that east looks about twice as bad and the data are too few to confirm it or rule it out. Unequal hours are exactly what the conditional test handles.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 13, 'A comparison finds no difference today on small counts. What would settle it?', '["More exposure: as the counts grow the interval narrows.", "A switch to the minlike p-value, which is more sensitive to differences on small counts.", "A lower confidence, chosen after seeing the result so that the interval excludes 1.", "Dropping the group with fewer events, which is the one adding the noise."]'::jsonb, 0, 'A finding of no difference on counts like UTOROGU''s 7 and 6 or ERHA''s 6 and 11 usually says more about the counts than the rates. Changing convention or confidence after seeing the data changes the claim and not the evidence, and dropping a group leaves nothing to compare.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 14, 'In the golden compare-second-zero, the central p-value is 0.039551 and the interval''s lower limit 1.100207 with no upper limit. Do the two agree?', '["No: an interval with no upper limit includes every ratio, so it cannot exclude 1.", "No: the p-value is below 0.05, while the lower limit is close to 1.", "The question has no answer, since the engine refused the case.", "Yes: the p-value is below 0.05 and the interval, 1.100207 and above, excludes 1."]'::jsonb, 3, 'An unbounded interval still has a lower edge, and 1.100207 is above 1, so equal rates are excluded, as the p-value below 0.05 also says. The engine returned the case with a null ratio and a reason; it refuses only when both groups are empty.'),
  ('safetystats', 'intermediate', 'module', 'm05-the-p-value-and-its-convention', 15, 'A colleague checks one of the engine''s p-values in R and finds a different number. What is the first thing to say?', '["That R has a rounding bug in its binomial tails, which the engine''s exact solver avoids.", "Which convention each figure uses: the engine''s is central, R''s poisson.test is minlike.", "That the engine uses the normal approximation, which R does not.", "That the two will match once the confidence is passed as 0.95."]'::jsonb, 1, 'The difference is a declared choice: the engine uses the central convention because it is the test its interval inverts, and on some inputs R''s minlike figure differs. Both are exact, and neither has a bug. The confidence does not enter either p-value.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 1, 'Which line writes the BLS worked example in the house form this course uses?', '["3.500000 per 200,000 hours, with an exact interval of 1.407182 to 7.211338 and no count needed", "3.500000 (7 cases in 400000 hours; exact interval 1.407182 to 7.211338)", "3.500000 per 200,000 hours (7 cases in 400000 hours; 95 percent exact interval 1.407182 to 7.211338)", "3.500000 per 200,000 hours (7 cases in 400000 hours; 95 percent exact interval 2.814363051520 to 14.422675361702)"]'::jsonb, 2, 'The house form carries the rate, the base, the count and hours it came from, and the interval with its confidence. One option drops the count and hours, one drops the base and the confidence, and one quotes the count limits where the rate limits belong.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 2, 'The BLS rate limits are 1.407182 and 7.211338. Where do they come from?', '["The count limits for 7 at 95 percent, 2.814363051520 and 14.422675361702, times 200,000 over 400000.", "The rate of 3.500000 plus and minus about two standard errors.", "The rate divided by and multiplied by a fixed factor of about two.", "The count limits for 7 at 90 percent, halved."]'::jsonb, 0, 'Each Garwood count limit is multiplied by the base over the hours, one half here. A symmetric normal interval would sit evenly around 3.500000, which these limits do not, and the 90 percent count limits would give a narrower pair.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 3, 'What does the BLS interval of 1.407182 to 7.211338 tell a reader about the firm''s 3.500000?', '["The firm''s rate will fall between 1.407182 and 7.211338 in 95 of the next hundred years it reports on the same hours.", "The printed figure is wrong, since the exact interval is centred on a value other than 3.500000.", "The rate is reliable, since BLS publishes the example.", "The true rate could be under half the printed figure or over twice it, and 7 cases cannot tell which."]'::jsonb, 3, 'The upper limit is more than twice the rate and the lower limit less than half, because 7 is a small count. The interval is about the true rate of this firm on these hours; it makes no forecast of future observed rates, and a lopsided interval is what an exact interval on a small count looks like.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 4, 'A firm with ten times the BLS cases in ten times the hours would print what, compared with the BLS example?', '["A rate ten times higher.", "The same 3.500000 with a far narrower interval.", "The same 3.500000 and the same interval.", "The same 3.500000 with an interval ten times as wide, since the hours are ten times greater."]'::jsonb, 1, 'Ten times the cases over ten times the hours is the same rate, and the width relative to the rate is a property of the count: more events, narrower interval, as on the IMO ladder. Nothing widens with more hours.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 5, 'IOGP''s 2024 observed FAR of 0.769438 rests on 32 fatalities in 4158877000 hours. Why does a figure built on billions of hours still carry an interval of 0.526295 to 1.086218?', '["The hours are rounded to the nearest million by IOGP, and that rounding is what the interval measures.", "The fixed base of 100,000,000 hours introduces uncertainty that a named base would not.", "The events are what the Poisson count model draws, and a fatality is rare even across an industry, so the count stays small.", "The interval is a percentile range of outcomes across IOGP''s member companies."]'::jsonb, 2, 'The interval comes from the count of fatalities exactly as the interval on a recordable rate comes from the count of recordables. 32 is a modest count, and the upper limit of 1.086218 is more than a third above the observed rate. The base only rescales, and the interval is on an estimated rate, with no percentile meaning.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 6, 'The IOGP 2024 upper limit is about twice its lower one; the BLS upper limit is about five times its lower. What sets that difference?', '["The count: 32 against 7.", "The hours: billions against hundreds of thousands, which is where the certainty of a rate comes from.", "The base: 100,000,000 hours against 200,000 hours, as a larger base narrows the interval.", "The confidence, which IOGP sets higher than BLS."]'::jsonb, 0, 'What sets the width relative to the rate is the number of events. The hours and base only rescale the count limits, and both intervals are at 95 percent.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 7, 'FAR is the one rate with a fixed base. What does the fixed base settle about an observed FAR?', '["Both the scale and the uncertainty, since a standard base leaves nothing to estimate.", "Nothing at all, since the base is still chosen by the caller of `fatalAccidentRate` on each call.", "Its interval, which the engine returns inside `fatalAccidentRate` as part of its basis block.", "What the number is per, and nothing about how sure it is."]'::jsonb, 3, '`fatalAccidentRate` takes no base argument, and its basis.standard reads IOGP safety performance indicators, FAR. The interval on an observed FAR comes from the fatality count through the Garwood construction, like any other rate, and the fixed base only rescales it.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 8, '2024 had 32 fatalities in 21 fatal incidents. The fatal incident rate on the same hours is 0.504944 per 100,000,000. How would its interval compare, relative to its rate, with the FAR''s?', '["Narrower, since fatal incidents are counted with less doubt than fatalities.", "Wider, since it rests on the smaller count.", "The same, since both rates share the same hours and the same fixed base.", "It has none, since incidents fall outside the Poisson count model."]'::jsonb, 1, 'Each count carries its own interval, and the width relative to the rate is set by the count: 21 against 32. Sharing hours and base only rescales. Fatal incidents are events like any other, so the Poisson count model applies to them too.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 9, 'Why does this course use no P label on a confidence interval?', '["P labels are reserved for one-sided limits such as the rule of three, which this course treats as derived.", "The engine returns intervals without names, so any label would have to be invented by the reader.", "A P label belongs to a range of outcomes, and a confidence interval here is on an estimated rate at a stated confidence.", "A P label would imply 90 percent confidence, and the course works at 95 percent."]'::jsonb, 2, 'Borrowing a percentile label would dress the Garwood interval up as a percentile of outcomes, which it is not. The house form writes the confidence as a percentage and calls the result an exact interval.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 10, 'A report writes the ABO crew as 0 per 200,000 hours (0 recordables in 41300 hours). What does the house form still need?', '["Its limits at a stated confidence: 0.000000 to 17.863823 at 95 percent.", "The rule of three figure, 14.527845, which is how a zero is conventionally bounded in a report.", "Nothing, since a zero rate has no uncertainty to report.", "The central 90 percent limit, 14.507178, labelled as the 95 percent limit."]'::jsonb, 0, 'The engine''s central 95 percent interval on 0 in 41300 hours is 0.000000 to 17.863823. The rule of three figure answers a one-sided question and 14.507178 is the central 90 percent limit, so labelling either as the 95 percent exact interval misstates it. A zero has an interval like any other count, and the house form puts it beside the rate.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 11, 'How does the house form write a comparison of two rates?', '["The p-value alone, since it summarises the whole comparison in one figure.", "Both rates on their bases, leaving the ratio for the reader to work out.", "The ratio and the minlike p-value, which readers in R will recognise.", "The rate ratio and what it compares, both counts and hours, the interval with its confidence, then the central p-value."]'::jsonb, 3, 'For ERHA: east over west 2.047326 (6 events in 240500 hours against 11 in 902700 hours; 95 percent interval 0.621694 to 6.039396; central p-value 0.256209). Name the convention whenever a p-value appears, because a reader checking it in R will find a different number on some inputs.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 12, 'Why does the house form state the confidence even when it is 95 percent?', '["The engine prints it automatically in every basis block, so leaving it out loses nothing.", "The same count gives different limits at different confidences.", "Only 95 percent intervals are exact.", "Readers assume 90 percent otherwise."]'::jsonb, 1, 'For a count of 7 the count upper limit is 13.148113802432 at 0.900000 and 14.422675361702 at 0.950000: different claims about the same data. The engine has no default confidence, so every interval was asked for at a level someone chose, and the report should say which.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 13, 'The BLS upper limit of 7.211338 agrees with the golden to 7.39e-16. What does that agreement mean?', '["A disagreement in the seventh decimal, which the six decimal print hides from the reader.", "The golden and the engine share one code path, so agreement is automatic whatever the value.", "Agreement to the limit of double precision.", "The limit is exact to 7.39e-16 of the true rate."]'::jsonb, 2, 'A relative difference of 7.39e-16 is at the resolution of a double, so the engine reproduces the independently computed golden. The golden was written by a separate oracle, and agreement with it says nothing about how close the limit is to the firm''s unknown true rate.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 14, 'The capstone for this tier asks for a zero events crew''s central 95 percent upper limit. Which method answers it?', '["The rule of three, 3 events over the crew''s hours on the 200,000 base, which the engine does not compute.", "`rateConfidenceInterval` with confidence 0.900000, whose upper limit is the one-sided 95 percent figure.", "`compareRates` against a crew with no events, whose p-value gives the limit.", "`rateConfidenceInterval` with a count of 0, the crew''s hours, the 200,000 base and confidence 0.95."]'::jsonb, 3, 'The field asks for the engine''s own central 95 percent upper limit. The rule of three would sit roughly a fifth lower on any hours, and the central 90 percent limit answers the one-sided question. Two groups with no events are refused by `compareRates`.'),
  ('safetystats', 'intermediate', 'module', 'm06-intervals-in-a-report', 15, 'The capstone asks for a rate-ratio interval between two named groups. Why does the order in which they are passed matter?', '["The ratio is the first group''s rate over the second''s, so swapping inverts the ratio and exchanges its limits.", "It does not matter, since the conditional test is symmetric in its two groups and returns one ratio to the caller.", "The engine sorts the two groups by their hours, so only the p-value depends on the order in which the caller passes them.", "The second group''s base is used for both."]'::jsonb, 0, 'Set the two groups in the order the brief gives: the engine''s rateRatio is count1 over hours1 against count2 over hours2, and passing them the other way round returns one over each figure with the ends exchanged. The p-value is the same either way, and `compareRates` takes no base.'),
  ('safetystats', 'intermediate', 'final', null, 1, 'On the IMO ladder, the row for 2 events in 200000 hours reads 0.242209 to 7.224688 per 200,000 hours, and the Garwood table''s count limits for 2 are 0.242209278544 and 7.224687667724. Why do the digits match?', '["The ladder is computed on a base of 1 over 1 hour, the same base the Garwood table itself is printed on in the course.", "At 2 events the Poisson distribution is symmetric about its mean, so the rate limits and count limits coincide.", "The base over the hours is 200,000 over 200000, which is one, so scaling leaves the count limits as they are.", "The ladder rounds every limit to the nearest count limit printed in the Garwood table."]'::jsonb, 2, 'A rate limit is the count limit times the base over the hours. With 200000 hours on the 200,000 base that multiplier is one, so the rate limits are the count limits printed to six decimals. The ladder uses the 200,000 base, and the Poisson distribution is skewed at every small count.'),
  ('safetystats', 'intermediate', 'final', null, 2, 'On the IMO ladder at 5 events, the width over rate column reads 2.008969. How is that figure formed?', '["The upper limit minus the lower limit, divided by the rate of 2.000000.", "The upper limit divided by the lower limit, 4.667333 over 0.649395.", "The upper limit divided by the rate, which measures how far the interval reaches above the estimate.", "The count of 5 divided by the square root of the hours on the row."]'::jsonb, 0, '4.667333 minus 0.649395, over 2.000000, is the width over rate the course gives as 2.008969. The upper over the lower is a different column, 7.187207 on that row, and the ladder has no square root column.'),
  ('safetystats', 'intermediate', 'final', null, 3, 'The Garwood count limits for 1 event are 0.025317807984 and 5.571643390939. The IMO ladder row for 1 event in 100000 hours reads 0.050636 to 11.143287. What links them?', '["Both are multiplied by 100000 over 200,000, the hours over the base.", "The ladder adds one event to the count before computing the limits, which doubles them.", "The ladder reports a 0.990000 interval where the table reports 0.950000.", "Both count limits are multiplied by 200,000 over 100000, which is two."]'::jsonb, 3, 'The rate limit is the count limit times the base over the hours, and 200,000 over 100000 is two: twice 0.025317807984 rounds to 0.050636 and twice 5.571643390939 to 11.143287. Inverting the fraction would halve them, and both tables are at 95 percent.'),
  ('safetystats', 'intermediate', 'final', null, 4, 'A site''s recordables tend to arrive in clusters, several people hurt in one incident. What does that mean for the Garwood interval on its count?', '["Nothing, since the Garwood interval is exact and so holds whatever the pattern of arrivals.", "Real counts scatter wider than the Poisson count model says, so the interval may understate the uncertainty.", "The interval becomes too wide, since clusters make counts more predictable.", "The engine refuses counts from clustered events."]'::jsonb, 1, 'The model assumes events arrive one at a time and independently, and the Garwood interval is exact for a count that follows it. Where one job injures several people the events are dependent and the scatter widens beyond the model''s. The engine cannot detect clustering and refuses nothing on that ground.'),
  ('safetystats', 'intermediate', 'final', null, 5, 'A league table sorts sites by their bare recordable rates. What does the table hide?', '["The base each site used, which is always the part of a rate that a league table leaves out of its columns.", "Nothing that matters, since each rate already divides out the hours that its own site worked in the year.", "Which rung of the IMO ladder each rate came from, and so how far its true rate might sit from it.", "Each site''s headcount, which sets its interval."]'::jsonb, 2, 'Two sites printing 2.000000 can rest on 1 event or on 100, with intervals of 0.050636 to 11.143287 and 1.627280 to 2.432536. Dividing by the hours makes rates comparable in scale and says nothing about how sure each one is. The engine takes no headcount.'),
  ('safetystats', 'intermediate', 'final', null, 6, 'For the BLS count of 7, the engine reads 28.845350723405 off the chi-square distribution on 16 degrees of freedom. Which figure does it then report as countUpper?', '["28.845350723405, since the quantile on 16 degrees of freedom is already the limit", "13.148113802432, the upper count limit that the Garwood table prints at 90 percent", "7.211338, which is the BLS rate upper limit on the 200,000 base", "14.422675361702"]'::jsonb, 3, 'The Garwood upper limit is chi2(1 - alpha/2; 2N + 2)/2, so it is half of 28.845350723405, which is 14.422675361702 and matches the engine''s countUpper. The unhalved quantile is twice the limit, 13.148113802432 belongs to 90 percent, and 7.211338 is a later step, scaled to a rate.'),
  ('safetystats', 'intermediate', 'final', null, 7, 'For a count above zero, which exported function does the engine use for each Garwood limit?', '["`chiSquareQuantile` for the lower limit, `chiSquareQuantileUpper` for the upper.", "`chiSquareQuantileUpper` for both limits, since each one leaves alpha/2 in a tail.", "`chiSquareQuantile` for both limits, at alpha/2 and at 1 minus alpha/2.", "`regularizedGammaQ` for both."]'::jsonb, 0, 'The engine solves the smaller tail directly. The lower limit has alpha/2 below it, which `chiSquareQuantile` asks for as it stands, and the upper has alpha/2 above it, which `chiSquareQuantileUpper` asks for directly. Asking the lower-tail function for 1 minus alpha/2 is the route the course shows losing digits as the tail probability shrinks. At a count of zero the lower limit is 0 and needs no quantile.'),
  ('safetystats', 'intermediate', 'final', null, 8, 'Which confidence value does `rateConfidenceInterval` accept?', '["95, read as a percentage and converted", "0.990000", "1, since certainty is a fraction", "0, as the smallest fraction"]'::jsonb, 1, 'The engine accepts a fraction strictly between 0 and 1. It refuses 95 with the message confidence must be a fraction strictly between 0 and 1, for example 0.95, and strictly excludes both 0 and 1: an interval at 1 would have no upper limit and one at 0 would promise nothing.'),
  ('safetystats', 'intermediate', 'final', null, 9, 'With confidence 0.95 the engine forms alpha as 0.050000000000000044. What does that do to the 95 percent interval?', '["It widens the interval slightly at every count, which is part of why the coverage sits above 0.95.", "It forces the engine onto the upper-tail route, since the lower-tail route cannot handle it at 95 percent.", "Nothing visible: alpha is off only in its seventeenth decimal, far below any digit the course prints.", "It makes the engine refuse 0.95 and ask for a percentage in its place."]'::jsonb, 2, '0.050000000000000044 differs from 0.05 by less than one part in ten to the fifteen, and at a tail of 0.025 the two routes agree to the last digit printed, 7.377758908228. The coverage excess comes from the whole-number count, and the upper-tail route is chosen for small tail probabilities, where the lower-tail route loses digits and at 1e-17 cannot be asked at all.'),
  ('safetystats', 'intermediate', 'final', null, 10, 'The course''s last row asks both quantile routes for a tail of 1e-17. What becomes of the route that works through 1 minus q?', '["It returns 78.287893161798, the same as the upper-tail route, to the last digit.", "It returns a relative error of 2.32e-5, the same as it does at 1e-15.", "It refuses with a message naming `confidence` as the field at fault.", "1 minus q rounds to exactly 1, so it cannot be asked the question at all."]'::jsonb, 3, 'At 1e-17 the double 1 minus q is 1, and a quantile at probability 1 has no finite answer. The upper-tail route still returns 78.287893161798, matching minus 2 ln q, and 2.32e-5 is the lower route''s error at 1e-15.'),
  ('safetystats', 'intermediate', 'final', null, 11, 'A reviewer sees coverage of 0.956795 at a true mean of 20.000000 and says the interval barely meets its promise there. What is the better reading?', '["It still meets the promise; the excess is smaller at larger means because the coverage steps are finer there.", "It falls short of the promise there, since 0.956795 is below 0.95 once rounding is removed.", "It shows the engine switches to a normal approximation above a mean of 10.", "It shows coverage peaks at larger means."]'::jsonb, 0, 'Every coverage in the table is at or above 0.95, and at 20.000000 the excess is the smallest because a larger mean spreads over more counts. The largest excess is at 3.500000, 0.990126. The interval is exact at every mean; no approximation is switched in.'),
  ('safetystats', 'intermediate', 'final', null, 12, 'For a count of 7 at 0.800000, the count limits are 3.894766804876 and 11.770914461548. How much of the miss does each tail hold?', '["20 percent in each tail, the whole of alpha, since a central interval places all of the miss on either side of it.", "10 percent in each tail.", "5 percent in each tail, the same as at 90 percent.", "0.800000 in the upper tail."]'::jsonb, 1, 'Alpha at 0.800000 is 20 percent, and the central interval splits it evenly, 10 percent below the lower limit and 10 percent above the upper. Putting the whole 20 percent in each tail would build a narrower interval than the one asked for.'),
  ('safetystats', 'intermediate', 'final', null, 13, 'At 95 percent the count of 7 has limits 2.814363051520 and 14.422675361702. Why can''t that interval be written as 7 plus or minus a single figure?', '["The engine''s rounding produces two different figures, which average to one single spread.", "A single figure would need a standard deviation, which the engine computes and hides.", "The interval is lopsided: the lower limit sits much closer to 7 than the upper one does.", "It can, as 7 plus or minus half the width of the interval."]'::jsonb, 2, 'The Poisson distribution is skewed to the right, so the Garwood interval stretches further above the count than below it. Writing it as the count plus or minus one figure would force a symmetry that is absent, which is one reason the engine returns two limits.'),
  ('safetystats', 'intermediate', 'final', null, 14, 'The engine calls its rate interval exact. Which property earns it that word?', '["The limits are correct to every decimal and carry no rounding at any precision the engine prints.", "The interval covers the true rate exactly 95 times in a hundred at every true mean.", "The limits are whole numbers of events.", "The limits come from the Poisson distribution itself, with no normal approximation standing in for it."]'::jsonb, 3, 'The chi-square form reads the limits off the Poisson distribution directly, which holds at the small counts safety work usually has. Coverage is at or above 0.95, never exactly 95 percent at every mean, and the limits are printed to twelve decimals as counts and six as rates.'),
  ('safetystats', 'intermediate', 'final', null, 15, 'Read off the chi-square form, what makes the Garwood table''s first row start at 0.000000000000?', '["The lower limit sits on 2N degrees of freedom, none at N of zero, so it is 0, the value the engine returns.", "The raw lower limit comes out negative, and the engine floors it at zero and flags that it did so in its result.", "The engine takes the lower limit from the rule of three whenever the count that it is passed is zero.", "Zero is the rounding of a very small positive limit."]'::jsonb, 0, 'In chi2(alpha/2; 2N)/2 the degrees of freedom are 2N, and at N of zero a chi-square on none has all its mass at 0. The probability reading agrees: zero or more events always happens, so no positive mean leaves alpha/2 there. The engine returns 0 for a zero count, the golden differs by 0, and nothing is floored or rounded, and the upper quantile on 2N + 2 degrees of freedom gives the row its 3.688879454114.'),
  ('safetystats', 'intermediate', 'final', null, 16, 'The ABO crew''s upper limit at 0.800000 is 11.150533 per 200,000 hours. What is the count upper limit behind it?', '["2.995732273554, the mean at which zero events has probability 5 percent, the one-sided 95 percent figure.", "2.302585092994, the mean at which zero events has probability 10 percent.", "3.688879454114, the count upper limit at 95 percent.", "0.800000, the confidence itself."]'::jsonb, 1, 'At 0.800000 half the miss is 10 percent, and the count upper limit at zero is minus ln of half the miss, 2.302585092994; times 200,000 over 41300 that is 11.150533. The 2.995732273554 figure belongs to 0.900000 and 3.688879454114 to 0.950000.'),
  ('safetystats', 'intermediate', 'final', null, 17, 'Before any scaling by hours, what does the engine return as countUpper for a zero count asked at 0.990000?', '["3.688879454114, the 95 percent count limit", "2.995732273554, the central 90 percent count limit", "5.298317366548", "25.657711, the 0.990000 limit as a rate"]'::jsonb, 2, 'At 0.990000 half the miss is half of one percent, and minus ln of that is 5.298317366548. Scaled by 200,000 over 41300 it becomes 25.657711 per 200,000 hours, a rate, which the question did not ask for.'),
  ('safetystats', 'intermediate', 'final', null, 18, 'Which formula gives the hours a crew with zero events needs before its central 95 percent upper limit reaches a target rate?', '["3 times 200,000 over the target, the rule of three turned around, which the engine confirms at every target row.", "The target times the crew''s hours over 200,000, which scales the limit down to the target directly.", "The target over the count upper limit, times the base.", "The count upper limit, 3.688879454114, times 200,000 over the target."]'::jsonb, 3, 'The rate upper limit is the count limit times 200,000 over the hours, so solving for the hours gives the count limit times 200,000 over the target; the engine returns the target exactly at each row, 737775.890823 hours for 1.000000. The rule of three would give fewer hours because it answers the one-sided question.'),
  ('safetystats', 'intermediate', 'final', null, 19, 'On any hours, the rule of three figure at zero events sits roughly a fifth below the engine''s central 95 percent upper limit. Why is the gap the same on every hours?', '["Both are a count, 3 and 3.688879454114, times the base over the same hours, so their ratio never moves.", "The gap depends on the hours and only looks like a fifth on the ABO crew''s 41300 hours.", "The engine adds a fixed allowance of about a fifth to every limit at zero events.", "The rule of three is defined as a fifth below the exact limit."]'::jsonb, 0, 'Scaling by base over hours multiplies both figures by the same factor, so their ratio is 3 against 3.688879454114 on every exposure; on the ABO hours that is 14.527845 against 17.863823. No allowance is added, and the rule of three is its own approximation to a one-sided limit.'),
  ('safetystats', 'intermediate', 'final', null, 20, 'A manager says the ABO crew''s clean record shows it is safer than UGHELLI, which recorded 0.776317 per 200,000 hours. What does the interval say?', '["The crew is safer, since 0 is below 0.776317 and both rates are taken on the same base of 200,000 hours.", "The crew''s upper limit is 17.863823, many times higher, so its clean record cannot show that.", "Neither can be judged, since the engine refuses to compare a zero with anything.", "The crew is less safe, since its upper limit is higher."]'::jsonb, 1, 'A zero on 41300 hours is a small amount of evidence. Its upper limit sits far above UGHELLI''s observed rate, so the record cannot rank the crew below it. A high upper limit shows only that the data are thin; it makes no case that the crew is worse.'),
  ('safetystats', 'intermediate', 'final', null, 21, 'What does the zero on the ABO crew''s 41300 hours measure?', '["It shows the true rate is zero over those hours, since no event was recorded at any point in them.", "Nothing, since an observed rate of 0 carries no information and so the interval is undefined.", "It bounds the true rate from above.", "It bounds the rate from below."]'::jsonb, 2, 'Zero is still a measurement. At 95 percent the true rate cannot be ruled out up to 17.863823 per 200,000 hours, and the lower limit is 0.000000, so the only bound the zero supplies is from above.'),
  ('safetystats', 'intermediate', 'final', null, 22, 'What is east''s share of the ERHA events, and what does the conditional test compare it with?', '["0.210374, set against the expected share of 0.352941 from the hours.", "0.352941, set against an even share of one half.", "0.128104, set against 0.05.", "0.352941, set against the expected share of 0.210374 from the hours."]'::jsonb, 3, 'East recorded 6 of the 17 events, a share of 0.352941, against 0.210374 of the hours. Under equal rates the expected share is the hour share. An even split would assume equal hours, and 0.128104 is the upper tail, the probability of a share at least that large.'),
  ('safetystats', 'intermediate', 'final', null, 23, 'The engine''s rate-ratio interval is Clopper-Pearson. In what sense is it exact in the same way the Garwood interval is?', '["It is the exact central interval for east''s binomial share of the events, converted into a ratio of rates with the hours.", "It is a normal interval on the log of the ratio, which is exact once the counts pass 10 on each side.", "It combines the two Garwood intervals, dividing one group''s limits by the other''s.", "It is exact only when both groups worked equal hours."]'::jsonb, 0, 'Conditioning turns the comparison into a binomial share, and Clopper-Pearson is its exact interval with half the miss in each tail, built like the Garwood interval. Each limit on the share becomes a ratio through the hours. A Wald log interval is an approximation, and dividing two separate intervals is no exact method.'),
  ('safetystats', 'intermediate', 'final', null, 24, 'The ERHA comparison is rerun with both sides reported on the 1,000,000 base. What is the rate ratio?', '["Five times 2.047326, since the IOGP base is five times the OSHA base and it scales both rates.", "2.047326, unchanged.", "One fifth of 2.047326, since the base moves into the denominator of the ratio.", "The engine refuses the 1,000,000 base."]'::jsonb, 1, 'The base appears in both rates and cancels in their ratio, which is why `compareRates` takes no base at all. A base scales a single rate; it never changes a ratio of two rates on the same base.'),
  ('safetystats', 'intermediate', 'final', null, 25, 'After the ERHA groups are swapped so that west comes first, what is the central p-value?', '["0.951727, now that the other tail is the observed one.", "0.128104, the smaller tail on its own.", "0.256209, the same as before.", "One minus 0.256209, since the question is reversed."]'::jsonb, 2, 'Swapping the groups exchanges the two tails, and the smaller one keeps its value, so twice it is unchanged. The ratio and its limits invert; the p-value does not. 0.128104 is a single tail left undoubled.'),
  ('safetystats', 'intermediate', 'final', null, 26, 'Which of these is an input to `compareRates`?', '["The base, on which both rates are then expressed before the ratio is taken.", "The headcount of each group, which sets the expected proportion.", "The common rate, to be tested against.", "The confidence."]'::jsonb, 3, '`compareRates` takes count1, exposureHours1, count2, exposureHours2 and confidence. The base cancels in a ratio, the expected proportion comes from the hours, and conditioning on the total removes the common rate.'),
  ('safetystats', 'intermediate', 'final', null, 27, 'In compare-first-zero the empty group comes first and the engine returns a ratio of 0.000000. In compare-second-zero the empty group comes second. What changes in the shape of the output?', '["The ratio becomes null with an unbounded upper limit and a finite lower limit, where before it was zero with a finite upper limit.", "Nothing, since the engine sorts the groups so that the empty one always comes first.", "The comparison is refused, since a zero in the denominator is undefined.", "The p-value becomes null."]'::jsonb, 0, 'Put the empty group first and the ratio is zero with a finite upper limit, 0.990863 in the golden; put it second and the ratio is something over zero, returned as null with upperUnbounded true and a finite lower limit, 1.100207. The p-value exists in both, 0.048748 and 0.039551.'),
  ('safetystats', 'intermediate', 'final', null, 28, 'Which call does `compareRates` refuse?', '["One with a first group that has no events, as in compare-first-zero.", "One with a group that has no hours.", "One with a second group that has no events, since its rate ratio is unbounded.", "One with counts under five, as a binomial on so few events is too coarse to be tested."]'::jsonb, 1, 'A group with no hours has no rate, and the engine names `exposureHours2` in that case; both groups empty is refused too. One empty group is a legitimate comparison, returned with a zero or an unbounded ratio, and no minimum count applies.'),
  ('safetystats', 'intermediate', 'final', null, 29, 'What is UTOROGU''s rate ratio of 3.445148?', '["North''s count over south''s count, 7 over 6.", "South''s rate over north''s, from the same counts and hours.", "North''s rate over south''s, from 7 events in 355200 hours and 6 in 1048900.", "The ratio of the two groups'' hours."]'::jsonb, 2, 'The rate ratio divides one rate by the other, each a count over its hours; the base cancels. The raw count ratio ignores that south worked far more hours, and the engine reports north over south because north is passed first.'),
  ('safetystats', 'intermediate', 'final', null, 30, 'Why is UTOROGU''s minlike p-value of 0.025879 labelled DERIVED?', '["It is derived from the central p-value by halving it, which is the minlike convention on every input.", "It is read off the rate-ratio interval.", "The engine computes it and hides it.", "The engine does not compute it; it is derived beside the engine''s central figure for comparison."]'::jsonb, 3, 'The engine returns one p-value, the central one, 0.051759. The minlike figure is the convention of R and scipy, computed outside the engine so the two can be set side by side. It is a different sum over the binomial, and halving the central figure is no general route to it.'),
  ('safetystats', 'intermediate', 'final', null, 31, 'A report reads UTOROGU''s central p-value of 0.051759 as nearly significant and writes that north''s rate is higher. What should it carry in place of that claim?', '["Both ends of the interval, 0.991404 and 12.408545, which leave equality and a very large gap both open.", "That north''s rate is higher, since 0.051759 is within rounding of 0.05 and so counts as significant.", "That the rates are equal, since the p-value is above 0.05 at the stated confidence and nothing was found.", "That the minlike figure of 0.025879 settles it."]'::jsonb, 0, 'The interval 0.991404 to 12.408545 includes 1 and also reaches far above it, and a report has to give both ends. Treating a p-value above 0.05 as a difference or as equality each tells half the story, and swapping to the minlike convention after seeing the result changes the rule and not the evidence.'),
  ('safetystats', 'intermediate', 'final', null, 32, 'ERHA''s interval is 0.621694 to 6.039396 and UTOROGU''s is 0.991404 to 12.408545. Which comparison is the thinner evidence, judged by the upper limit over the lower?', '["ERHA, since its p-value of 0.256209 is the larger of the two and so marks the weaker evidence.", "UTOROGU, whose upper limit is over twelve times its lower where ERHA''s is under ten times.", "UTOROGU, since it has fewer events in total than ERHA, and the total count alone sets the width.", "They are equally thin, since both include 1."]'::jsonb, 1, 'The ratio of the limits measures how much the data leave open, and UTOROGU''s spans a wider multiple, from just below 1 to 12.408545. A larger p-value is no measure of how wide the uncertainty is, and a total count alone does not settle the width of a ratio''s interval, which depends on both counts and the hour split.'),
  ('safetystats', 'intermediate', 'final', null, 33, 'What does the size of a p-value tell you about the size of a difference between two rates?', '["A smaller p-value always means a larger rate ratio.", "The p-value is the probability that the rate ratio is 1, so its size measures how far the ratio sits from equality.", "Nothing on its own; the rate-ratio interval answers that.", "The p-value divided by 0.05 is the ratio."]'::jsonb, 2, 'A p-value is the probability, under equal rates, of a split at least as lopsided as the one seen. It mixes the size of a difference with the size of the counts, so a large difference on few events and a small one on many can read alike. The interval gives the size and the verdict together.'),
  ('safetystats', 'intermediate', 'final', null, 34, 'Why does the lesson say to report the interval first and the central p-value beside it?', '["The p-value is less accurate than the interval at six decimals, so it belongs second in the line.", "Readers in R will only recognise the interval.", "The p-value is optional in the house form.", "The interval carries the size of the difference as well as the verdict."]'::jsonb, 3, 'The interval says how large a difference the data allow at each end and, by whether it includes 1, gives the same verdict as the central p-value. The p-value is kept as a check and must name its convention. Both are printed to six decimals.'),
  ('safetystats', 'intermediate', 'final', null, 35, 'A report must carry IOGP''s 2024 observed FAR with its uncertainty. Which version follows the course''s house form?', '["0.769438 per 100,000,000 hours (32 fatalities in 4158877000 hours; 95 percent exact interval 0.526295 to 1.086218)", "0.77 per 100,000,000 hours (32 fatalities in 4158877000 hours; 95 percent exact interval 0.526295 to 1.086218)", "0.769438 per 100,000,000 hours (21 fatal incidents in 4158877000 hours; 95 percent exact interval 0.526295 to 1.086218)", "0.769438 (32 fatalities; 95 percent exact interval 0.526295 to 1.086218)"]'::jsonb, 0, 'The house form keeps six decimals, the base, the count and hours, and the interval with its confidence. The published 0.77 drops the precision, 21 is the fatal incident count behind a different rate, 0.504944, and the last line drops the base and the hours.'),
  ('safetystats', 'intermediate', 'final', null, 36, 'IOGP''s 2024 observed FAR is 0.769438 with an upper limit of 1.086218. How far above the observed rate does that limit sit?', '["About twice it, as the limits on 32 events span a factor of two.", "More than a third above it.", "Within rounding of it, since the hours run to billions.", "Exactly one third above it, which is the Garwood rule at 95 percent."]'::jsonb, 1, '1.086218 over 0.769438 is more than one and a third: 32 events is a modest count even on 4158877000 hours. The factor of about two is the upper limit over the lower one, 0.526295, and no fixed fraction applies at every count.'),
  ('safetystats', 'intermediate', 'final', null, 37, 'To report UGHELLI''s fatality-free year properly, what should sit beside its FAR of 0.000000?', '["Nothing more, since a zero FAR has no interval and the fixed base already states what it is per.", "The IOGP 2024 interval of 0.526295 to 1.086218, as the reference a zero FAR is read against.", "Its 0 fatalities in 2318640 hours and an exact upper limit at a stated confidence, from the zero events arithmetic on the FAR base.", "The rule of three figure, which is how the house form writes a zero."]'::jsonb, 2, 'A zero is reported with its upper limit, and the same zero events arithmetic bounds a fatality count on the FAR base. The IOGP interval belongs to a different count on different hours, and the house form writes the engine''s exact interval with its confidence.'),
  ('safetystats', 'intermediate', 'final', null, 38, 'Why does the house form keep six decimals, the count whole and the hours as stated?', '["Because the engine refuses to print a rate at any other precision or with rounded hours.", "Because six decimals is the grading tolerance of the course.", "Because the confidence requires it.", "So that anyone with the engine can check the line figure by figure."]'::jsonb, 3, 'A report that follows the form can be recomputed line by line from its own count, hours and base. The precision is the course''s printing convention; the engine computes at full precision and tolerances are made elsewhere.'),
  ('safetystats', 'intermediate', 'final', null, 39, 'A comparison line in a report quotes a p-value without naming its convention. What is the risk?', '["A reader who checks it in R finds a different number on some inputs and cannot tell which is right.", "None, since every exact test gives the same p-value on the same counts once the hours are fixed.", "The p-value will be read as a percentile.", "The engine''s p-value is only valid with its name."]'::jsonb, 0, 'The engine''s p-value is central; R''s poisson.test and scipy''s binomtest are minlike, and on 14 of the 399 comparisons the course swept they disagree with the engine''s interval. Naming the convention lets a reader compare like with like.'),
  ('safetystats', 'intermediate', 'final', null, 40, 'UTOROGU''s comparison rests on 7 events against 6. How does the IMO ladder help explain why it found no clear difference?', '["The ladder shows every rate below 20 events is unreliable, so any comparison on fewer is refused.", "A single count of that size already carries a wide interval, and a ratio of two such counts inherits both widths.", "The ladder holds the rate at 2.000000, which is close to both UTOROGU rates.", "It does not; the ladder is about single rates only."]'::jsonb, 1, 'On the ladder the upper limit is 3.835008 times the lower at 10 events, and a comparison of two counts in that range inherits the width of both. So a finding of no difference on counts like these usually says more about the counts than the rates. Nothing is refused for being small.'),
  ('safetystats', 'intermediate', 'final', null, 41, 'In the ERHA comparison, which figure is the probability that east records 6 or fewer of the 17 events if the rates are equal?', '["0.128104, the upper tail, which covers 6 or more of the 17.", "0.256209, the central p-value.", "0.951727, the lower tail.", "0.210374, the expected proportion."]'::jsonb, 2, 'The lower tail counts the observed 6 and everything below it, 0.951727. The upper tail counts 6 and above, 0.128104, and is the smaller, so it is the one the central p-value doubles. 0.210374 is the binomial probability for a single event.'),
  ('safetystats', 'intermediate', 'final', null, 42, 'A report writes the BLS case as 3.500000 per 200,000 hours (7 cases in 400000 hours; 90 percent exact interval 1.407182 to 7.211338). What is wrong with the line?', '["Nothing, since the house form lets a writer name any confidence as long as some confidence is named.", "The limits should be the count limits, 2.814363051520 and 14.422675361702, as the house form quotes counts.", "The rate should read 3.5, as BLS publishes it.", "The confidence label: those are the 95 percent limits."]'::jsonb, 3, 'Half of the 95 percent count limits for 7, 2.814363051520 and 14.422675361702, gives 1.407182 and 7.211338; the 90 percent count limits, 3.285315691895 and 13.148113802432, would give a narrower pair. The house form quotes rate limits at six decimals, and a wrong confidence label is a wrong claim.');
